#!/usr/bin/env bash
# Build or preview the documentation site (docs-site/ -> site/).
#
#   scripts/docs.sh build   # strict build into site/
#   scripts/docs.sh serve   # live preview on http://localhost:8000
#
# Needs uv (https://docs.astral.sh/uv/) and curl.
set -euo pipefail

VIEWER_VERSION="0.2.0" # @containerlab/clab-viewer, renders the topology diagrams

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$root"
mode="${1:-build}"
shift || true

# The ReDoc page reads the OpenAPI spec generated by `task swag`.
cp docs/swagger.json docs/swagger.yaml docs-site/api/

# Fetch the published viewer bundle once per version.
viewer_dir="docs-site/assets/viewer"
if [[ "$(cat "$viewer_dir/.version" 2>/dev/null)" != "$VIEWER_VERSION" ]]; then
  tmp="$(mktemp -d)"
  trap 'rm -rf "$tmp"' EXIT
  curl -fsSL "https://registry.npmjs.org/@containerlab/clab-viewer/-/clab-viewer-${VIEWER_VERSION}.tgz" \
    | tar -xz -C "$tmp"
  rm -rf "$viewer_dir"
  cp -R "$tmp/package/dist" "$viewer_dir"
  echo "$VIEWER_VERSION" >"$viewer_dir/.version"
fi

case "$mode" in
  build) exec uv run --frozen zensical build --strict --clean "$@" ;;
  serve) exec uv run --frozen zensical serve "$@" ;;
  prepare) ;;
  *) echo "usage: $0 [build|serve|prepare]" >&2; exit 2 ;;
esac
